class Solution {
    public List<Integer> pancakeSort(int[] arr){
        List<Integer> moves=new ArrayList<>();
        for(int size=arr.length;size>1;size--){
            int index=0;
            for(int i=1;i<size;i++)if(arr[i]>arr[index])index=i;
            if(index==size-1)continue;
            if(index>0){
                flip(arr,index+1);
                moves.add(index+1);
            }
            flip(arr,size);
            moves.add(size);
        }
        return moves;
    }
    private void flip(int[] arr,int length){
        for(int left=0,right=length-1;left<right;left++,right--){
            int temporary=arr[left];
            arr[left]=arr[right];
            arr[right]=temporary;
        }
    }
}

